    "kk": "AI полиглот",
    "ky": "NERIVA",
    "pl": "Poliglota AI",
    "pt": "Poliglota AI",
    "ro": "NERIVA",
    "uk": "Поліглот AI",
    "uz": "NERIVA",
    "ko": "다중언어 AI",
    "ja": "多言語AI",
    "zh": "多语言人工智能"
